[
    {
        "cwe_id": 79,
        "cwe_name": "Cross-site Scripting",
        "description": "XSS vulnerabilities allow attackers to inject malicious scripts into web pages viewed by other users",
        "sast_tool": "Generic",
        "rule_id": "CWE-79",
        "language": ["javascript", "typescript", "html"],
        "pattern": "(\\b(innerHTML|outerHTML|document.write|eval)\\s*=|\\b(innerHTML|outerHTML|document.write|eval)\\s*\\=)",
        "severity": "High",
        "examples": {
            "bad": [
                "element.innerHTML = user_input;",
                "document.write(userInput);"
            ]
        },
        "remediation": "Use proper escaping or sanitization for user input before rendering. Use DOM APIs instead of innerHTML where possible."
    },
    {
        "cwe_id": 89,
        "cwe_name": "SQL Injection",
        "description": "SQL injection allows attackers to execute arbitrary SQL commands",
        "sast_tool": "Generic",
        "rule_id": "CWE-89",
        "language": ["javascript", "python", "java"],
        "pattern": "(\\b(Exec|execute|query)\\s*\\([^)]*\\+\\s*[a-zA-Z_][a-zA-Z0-9_]*\\s*\\+[^)]*\\))",
        "severity": "High",
        "examples": {
            "bad": [
                "query = \"SELECT * FROM users WHERE id = \" + userId;",
                "db.execute(\"SELECT * FROM \" + table + \" WHERE user = \" + user);"
            ]
        },
        "remediation": "Use parameterized queries or prepared statements to prevent SQL injection"
    },
    {
        "cwe_id": 20,
        "cwe_name": "Input Validation",
        "description": "Insufficient input validation can lead to various vulnerabilities",
        "sast_tool": "Generic",
        "rule_id": "CWE-20",
        "language": ["javascript", "python", "java"],
        "pattern": "(\\b([a-zA-Z_][a-zA-Z0-9_]*\\s*=\\s*[\"'].*[\"']|[\"'].*[\"']\\s*=\\s*[a-zA-Z_][a-zA-Z0-9_]*)\\s*\\b)",
        "severity": "Medium",
        "examples": {
            "bad": [
                "var userInput = req.body.username;",
                "param = request.getParameter('input');"
            ]
        },
        "remediation": "Validate all inputs against a whitelist of expected values or use proper sanitization techniques"
    }
]

